(4909179, 711284, 52549, '<td valign="top">Brilliant, creative idea. Love it.</td>', 'Brilliant, creative idea. Love it.', '2008-08-25 06:29:33.000000', NULL, 0),
(4909180, 711543, 52549, '<td valign="top">Great textures and perspective, LOVE the colors.</td>', 'Great textures and perspective, LOVE the colors.', '2008-08-25 06:32:42.000000', NULL, 0),
(4909181, 711368, 20608, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by johnmcboston:</b></div><hr/><i> eh... </i></td></tr></table> <br/> <br/>Simple really... 3x3=9</td>', 'Originally posted by johnmcboston: eh...   Simple really... 3x3=9', '2008-08-25 06:32:50.000000', NULL, 0),
(4909226, 711220, 37529, '<td valign="top">Just an excellent shot.  The person how said "photos are made not taken" knew what he was talking about as I believe it was Ansel Adams.</td>', 'Just an excellent shot.  The person how said "photos are made not taken" knew what he was talking about as I believe it was Ansel Adams.', '2008-08-25 07:47:53.000000', NULL, 0),
(4909227, 711471, 30982, '<td valign="top">Was I the only one who saw graph paper?  I like GeneralE''s pixel theory - far more appropriate to the current medium.  (I''m old school.  I remember graph paper.  I loved graph paper.)</td>', 'Was I the only one who saw graph paper?  I like GeneralE''s pixel theory - far more appropriate to the current medium.  (I''m old school.  I remember graph paper.  I loved graph paper.)', '2008-08-25 07:48:58.000000', NULL, 0),
(4909230, 711518, 53690, '<td valign="top">Yes, your first blue!  Of course this wasn''t the <i>most</i> time-consuming shot you''ve ever done, but it certainly came close.  It''s great to see you on the front page after watching your score all week.  This win was well-deserved and long-overdue.  Congratulations, baby!</td>', 'Yes, your first blue!  Of course this wasn''t the most time-consuming shot you''ve ever done, but it certainly came close.  It''s great to see you on the front page after watching your score all week.  This win was well-deserved and long-overdue.  Congratulations, baby!', '2008-08-25 07:51:56.000000', NULL, 0),
